const limit = 100;
if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('Inventory limit must be an integer from 1 to 100');
return [{ json: { limit } }];

const limit = $('Configure Inventory').first().json.limit;
const messages = $input.first().json.messages;
if (messages === undefined) return [{ json: { hasMessage: false } }];
if (!Array.isArray(messages)) throw new Error('Unexpected Gmail message list');
if (messages.length === 0) return [{ json: { hasMessage: false } }];
if (messages.length > limit) throw new Error('Gmail message list exceeds the configured limit');
const ids = new Set();
return messages.map((message) => {
  if (typeof message.id !== 'string' || !/^[a-zA-Z0-9_-]+$/.test(message.id) || ids.has(message.id)) throw new Error('Unexpected or duplicate Gmail message ID');
  ids.add(message.id);
  return { json: { hasMessage: true, id: message.id } };
});

const messages = $input.all();
const limit = $('Configure Inventory').first().json.limit;
if (messages.length > limit) throw new Error('Metadata count exceeds the configured limit');
const groups = new Map();
const ids = new Set();
let unknownSenderCount = 0;
for (const item of messages) {
  const message = item.json;
  if (typeof message.id !== 'string' || !/^[a-zA-Z0-9_-]+$/.test(message.id) || ids.has(message.id) || !Array.isArray(message.payload?.headers)) throw new Error('Unexpected Gmail metadata response');
  ids.add(message.id);
  const headers = message.payload.headers;
  if (headers.some((header) => !header || typeof header.name !== 'string' || typeof header.value !== 'string')) throw new Error('Unexpected Gmail metadata headers');
  const values = (name) => headers.filter((header) => header.name.toLowerCase() === name).map((header) => header.value);
  const from = values('from');
  const raw = from.length === 1 ? from[0].trim() : '';
  const angle = raw.match(/^([^<>@]*)<([^<>]+)>\s*$/);
  const address = (angle ? angle[2] : raw).trim().toLowerCase();
  const parts = address.split('@');
  const local = parts[0];
  const domain = parts[1];
  const atom = "[a-z0-9!#$%&'*+\\/?^_`{|}~-]+";
  const validLocal = new RegExp('^' + atom + '(?:\\.' + atom + ')*$').test(local);
  const validDomain = domain && domain.split('.').every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label));
  if (parts.length !== 2 || !validLocal || !validDomain || local.length > 64 || domain.length > 253) { unknownSenderCount++; continue; }
  if (!groups.has(address)) groups.set(address, { sender: address, count: 0, signals: { listUnsubscribe: 0, bulkOrListPrecedence: 0, noReplyAddress: 0 } });
  const group = groups.get(address);
  group.count++;
  if (values('list-unsubscribe').some((value) => value.trim() !== '')) group.signals.listUnsubscribe++;
  if (values('precedence').some((value) => /^(bulk|list|junk)$/i.test(value.trim()))) group.signals.bulkOrListPrecedence++;
  if (/^(no[-_.]?reply|do[-_.]?not[-_.]?reply|notifications?)$/.test(local)) group.signals.noReplyAddress++;
}
const senders = [...groups.values()].map((group) => ({ ...group, category: Object.values(group.signals).some((count) => count > 0) ? 'potential_newsletter_or_automated' : 'no_signal', safeToDelete: false })).sort((a, b) => b.count - a.count || a.sender.localeCompare(b.sender));
return [{ json: { messagesAnalyzed: messages.length, unknownSenderCount, senders } }];
